INSERT INTO public.campaigns (id, slug, title, description, difficulty, status, icon_key, sort_order, created_at, published_at) VALUES ('a3357d76-9593-42dd-84d0-1972968d8eca', 'code-foundations', 'Code Foundations', 'Start here if you''re brand new to programming. Learn the core building blocks you''ll use in every language, then put them into practice.', 0, 1, NULL, 0, '2026-11-21 20:31:36.31875+00', '2026-11-21 20:31:36.323188+00') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_modules (id, "CampaignId", title, description, sort_order, campaign_id) VALUES ('026e9e56-401d-4eab-aae1-8a19f8a52852', 'a3357d76-9593-42dd-84d0-1972968d8eca', 'Control Flow', 'Make decisions and repeat work in your code.', 1, 'a3357d76-9593-42dd-84d0-1972968d8eca') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_modules (id, "CampaignId", title, description, sort_order, campaign_id) VALUES ('52a77e27-4f98-40f8-a95c-ae96a156ab5e', 'a3357d76-9593-42dd-84d0-1972968d8eca', 'Getting Started', 'What programming is, and how to write and run your first lines of code.', 0, 'a3357d76-9593-42dd-84d0-1972968d8eca') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_modules (id, "CampaignId", title, description, sort_order, campaign_id) VALUES ('abab675a-8f3a-445d-b2ce-f15761297e37', 'a3357d76-9593-42dd-84d0-1972968d8eca', 'Functions', 'Package up logic so you can reuse it.', 2, 'a3357d76-9593-42dd-84d0-1972968d8eca') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_units (id, "CampaignModuleId", title, content, unit_type, estimated_minutes, sort_order, campaign_module_id) VALUES ('06fce7a6-e5d7-4c73-8974-fcd615bee5a9', 'abab675a-8f3a-445d-b2ce-f15761297e37', 'Practice: Two Sum', 'Write a function that finds two numbers in a list that add up to a target value.', 1, 20, 1, 'abab675a-8f3a-445d-b2ce-f15761297e37') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_units (id, "CampaignModuleId", title, content, unit_type, estimated_minutes, sort_order, campaign_module_id) VALUES ('30bb228a-e871-403b-bb16-de3ca5e97d6d', '52a77e27-4f98-40f8-a95c-ae96a156ab5e', 'Variables and Data Types', 'A variable is a named container for a value. Values come in a few basic types — numbers, text (strings), and true/false (booleans) — and the type determines what you can do with a value, like adding two numbers or joining two strings together.', 0, 10, 1, '52a77e27-4f98-40f8-a95c-ae96a156ab5e') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_units (id, "CampaignModuleId", title, content, unit_type, estimated_minutes, sort_order, campaign_module_id) VALUES ('4b4cb2d2-06ed-4264-a24d-94b7fec6bb58', '026e9e56-401d-4eab-aae1-8a19f8a52852', 'Loops', 'A loop repeats a block of code until a condition is no longer true, so you can process a list of items or repeat an action a fixed number of times without writing it out by hand.', 0, 10, 1, '026e9e56-401d-4eab-aae1-8a19f8a52852') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_units (id, "CampaignModuleId", title, content, unit_type, estimated_minutes, sort_order, campaign_module_id) VALUES ('639c4271-6109-4dbf-b2b9-fa4f57d1615e', '026e9e56-401d-4eab-aae1-8a19f8a52852', 'Practice: Hello or Goodbye', 'Put conditionals to work: given a name, decide whether to greet or say farewell.', 1, 15, 2, '026e9e56-401d-4eab-aae1-8a19f8a52852') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_units (id, "CampaignModuleId", title, content, unit_type, estimated_minutes, sort_order, campaign_module_id) VALUES ('8a389248-722b-4836-9e05-ee85f1541136', '52a77e27-4f98-40f8-a95c-ae96a156ab5e', 'What Is Programming?', 'A program is a sequence of instructions a computer follows, one step at a time. Every app, website, and game you''ve ever used is built from the same small set of building blocks: storing information, making decisions, and repeating work. This course walks through those building blocks from scratch.', 0, 5, 0, '52a77e27-4f98-40f8-a95c-ae96a156ab5e') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_units (id, "CampaignModuleId", title, content, unit_type, estimated_minutes, sort_order, campaign_module_id) VALUES ('9ea1d9ac-2abc-489d-985c-a29faea5f475', 'abab675a-8f3a-445d-b2ce-f15761297e37', 'Foundations Check', 'A short check-in on variables, conditionals, loops, and functions before you move on to the next path.', 2, 10, 2, 'abab675a-8f3a-445d-b2ce-f15761297e37') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_units (id, "CampaignModuleId", title, content, unit_type, estimated_minutes, sort_order, campaign_module_id) VALUES ('d071efc8-86fe-41b6-990e-dd2cfb4ff8f5', 'abab675a-8f3a-445d-b2ce-f15761297e37', 'Writing Functions', 'A function packages up a sequence of steps under a name, so you can run that logic again elsewhere without copying it. Functions take inputs (parameters) and can hand back a result (a return value).', 0, 10, 0, 'abab675a-8f3a-445d-b2ce-f15761297e37') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_units (id, "CampaignModuleId", title, content, unit_type, estimated_minutes, sort_order, campaign_module_id) VALUES ('db2fea59-7c76-4b78-8eba-af86f076a77b', '026e9e56-401d-4eab-aae1-8a19f8a52852', 'Conditionals', 'An if statement runs a block of code only when a condition is true, and an else branch runs otherwise. Chaining conditions lets a program react differently depending on the data it''s given.', 0, 10, 0, '026e9e56-401d-4eab-aae1-8a19f8a52852') ON CONFLICT DO NOTHING;
INSERT INTO public.campaign_units (id, "CampaignModuleId", title, content, unit_type, estimated_minutes, sort_order, campaign_module_id) VALUES ('ecd60701-363e-4372-bf7e-333e4ec22687', '52a77e27-4f98-40f8-a95c-ae96a156ab5e', 'Your First Program', 'Most languages start with a program that prints a message to the screen. Writing, running, and seeing the output of your first program is the fastest way to confirm your environment works before building anything more complex.', 0, 10, 2, '52a77e27-4f98-40f8-a95c-ae96a156ab5e') ON CONFLICT DO NOTHING;
INSERT INTO public.unit_problems (id, "CampaignUnitId", problem_id, sort_order, campaign_unit_id) VALUES ('2b577035-493b-41f7-bdf9-665a1c70f309', '06fce7a6-e5d7-4c73-8974-fcd615bee5a9', 'b84aded7-a976-4702-be1d-357dab06b5c7', 0, '06fce7a6-e5d7-4c73-8974-fcd615bee5a9') ON CONFLICT DO NOTHING;
